              <li v-for="log in state.logs" :key="log.id"><span class="w-20 shrink-0 text-muted">{{ dayLabel(log.climbedAtDate) }}</span><span class="flex-1 min-w-0 [overflow-wrap:anywhere]"><strong :class="{ 'text-success': log.topped }">{{ logKind(log) }}</strong><span v-if="state.selected.leadEnabled && !state.selected.leadRequired && typeof log.lead === 'boolean'" class="muted text-muted"> · {{ log.lead ? 'Lead' : 'Toprope' }}</span></span><button class="secondary flex items-center justify-center gap-2 min-h-12 px-3 rounded-[4px] text-[.75rem] font-semibold border border-solid border-line bg-surface text-error" :disabled="state.ascentBusy || state.busy || state.needsLogin || !state.connected" :aria-busy="state.ascentAction === `${state.selected.id}:log:${log.id}`" :aria-label="`Delete ${logKind(log)} from ${dayLabel(log.climbedAtDate)}`" @click="deleteLog(log)"><span v-if="state.ascentAction === `${state.selected.id}:log:${log.id}`" class="spinner inline-block w-4.5 h-4.5 [border:2px_solid_var(--line)] border-t-accent rounded-full shrink-0 animate-spin" aria-hidden="true" /><span v-else>Delete</span></button></li>
            </ul>
