          <div class="detail-panel p-3.5 mt-2.5 border border-solid border-line rounded-[7px] bg-panel [&>h2]:mb-3 [&>p]:mb-3 [&>p]:text-[.8rem]"><h2>Your ascents</h2><dl class="detail-grid grid grid-cols-2 [gap:14px_18px] m-0 [&_dt]:text-muted [&_dt]:text-[.72rem] [&_dt]:mb-0.75 [&_dd]:m-0 [&_dd]:text-[.85rem] [&_dd]:font-medium [&_dd]:[overflow-wrap:anywhere]"><div><dt>Attempts</dt><dd>{{ state.selected.climbUser?.totalTries || 0 }}</dd></div><div><dt>Best ascent</dt><dd>{{ ascentLabel(state.selected.climbUser?.tickType) }}</dd></div><div><dt>Your grade</dt><dd>{{ frenchGrade(state.selected.climbUser?.grade) }}</dd></div><div><dt>Score</dt><dd>{{ score(state.selected.grade, state.selected.climbUser?.tickType || 0) ?? '—' }}</dd></div><div><dt>First attempt</dt><dd>{{ dateLabel(state.selected.climbUser?.triedFirstAtDate) }}</dd></div><div><dt>First top</dt><dd>{{ dateLabel(state.selected.climbUser?.tickedFirstAtDate) }}</dd></div></dl></div>
          <div class="detail-panel p-3.5 mt-2.5 border border-solid border-line rounded-[7px] bg-panel [&>h2]:mb-3 [&>p]:mb-3 [&>p]:text-[.8rem]"><div class="section-heading flex justify-between items-center gap-3 [margin:16px_0_4px] [&_.muted]:text-[.72rem]"><h2>Community</h2><span v-if="state.communityBusy" class="spinner inline-block w-4.5 h-4.5 [border:2px_solid_var(--line)] border-t-accent rounded-full shrink-0 animate-spin" aria-label="Loading community data" /></div><div v-if="state.communityError" class="notice error flex items-center justify-between flex-wrap gap-2.5 p-3 mb-3 bg-soft [border-left:3px_solid_var(--accent)] text-[.8rem] [&.error]:text-error [&.error]:bg-error-bg [&.error]:border-l-error [&_button]:px-3 [&_button]:py-2 [&_button]:border [&_button]:border-solid [&_button]:border-[currentColor] [&_button]:rounded-[3px] [&_button]:text-inherit [&_button]:bg-transparent" role="alert">{{ state.communityError }}<button @click="openRoute(state.selected!)">Retry</button></div><template v-if="state.community"><h3>Grade votes</h3>
            <template v-if="gradeVoteTotal">
              <div class="grade-vote-summary flex items-baseline flex-wrap gap-2 mb-3 [&_>_strong]:text-[1.35rem] [&_>_span]:text-muted [&_>_span]:text-[.75rem]"><strong>{{ mostVotedGrades }}</strong><span>Most voted · {{ gradeVoteTotal }} {{ gradeVoteTotal === 1 ? 'vote' : 'votes' }}</span></div>
              <ul class="grade-vote-list [&_li.your-grade-vote_.grade-vote-track>span]:bg-accent list-none p-0 m-0 [&_li]:px-0 [&_li]:py-2.5 [&_li]:border-t [&_li]:border-solid [&_li]:border-t-line" aria-label="Community grade votes">
                <li v-for="vote in gradeVotes" :key="vote.grade" :class="{ 'your-grade-vote': vote.grade === state.selected.climbUser?.grade }">
                  <div class="grade-vote-label flex items-center flex-wrap gap-2 mb-1.5 [&_>_strong]:text-[.95rem]"><strong>{{ frenchGrade(vote.grade) }}</strong><span v-if="vote.grade === state.selected.grade" class="grade-vote-tag [padding:2px_5px] bg-soft text-muted rounded-[3px] text-[.65rem] [&.your-vote-tag]:bg-accent [&.your-vote-tag]:text-accent-text">Route grade</span><span v-if="vote.grade === state.selected.climbUser?.grade" class="grade-vote-tag your-vote-tag [padding:2px_5px] bg-soft text-muted rounded-[3px] text-[.65rem] [&.your-vote-tag]:bg-accent [&.your-vote-tag]:text-accent-text">Your vote</span></div>
                  <div class="grade-vote-result flex items-center flex-wrap gap-2.5"><span class="grade-vote-track flex-1 min-w-20 h-2.5 rounded-[3px] bg-soft overflow-hidden [&_>_span]:block [&_>_span]:h-[100%] [&_>_span]:bg-muted [&_>_span]:rounded-[inherit]" aria-hidden="true"><span :style="{ width: `${vote.count / gradeVoteTotal * 100}%` }" /></span><span class="grade-vote-count text-[.75rem] tabular-nums"><strong>{{ vote.count }}</strong> {{ vote.count === 1 ? 'vote' : 'votes' }} <span class="muted text-muted">· {{ Math.round(vote.count / gradeVoteTotal * 100) }}%</span></span></div>
