            <h3>Rating <span class="muted text-muted">{{ communityRating }}</span></h3><div class="rating-row flex items-center gap-2.5 [margin:8px_0] text-muted text-[.75rem] [&_meter]:flex-1" v-for="vote in state.community.ratingVoteStats" :key="vote.stars"><span>{{ vote.stars }} stars</span><meter :value="vote.count" :max="Math.max(...state.community.ratingVoteStats.map(item => item.count), 1)" :aria-label="`${vote.count} votes for ${vote.stars} stars`" /><span>{{ vote.count }}</span></div><h3>Toppers</h3><p v-if="state.community.toppersUnavailable" class="muted text-muted">TopLogger has not made the toppers list available.</p><p v-else-if="!state.community.toppers.length" class="muted text-muted">No public tops yet.</p><ul v-else class="toppers list-none p-0 [&_li]:flex [&_li]:items-center [&_li]:gap-2 [&_li]:flex-wrap [&_li]:px-0 [&_li]:py-2.5 [&_li]:border-t [&_li]:border-solid [&_li]:border-t-line [&_li]:text-[.8rem] [&_svg]:w-4 [&_svg]:text-accent [&_.muted]:text-[.72rem] [&_.muted]:ml-auto"><li v-for="topper in state.community.toppers" :key="topper.id"><AppIcon name="check" /><span>{{ topper.user?.fullName || 'Anonymous climber' }}</span><span class="muted text-muted">{{ ascentLabel(topper.tickType) }}<template v-if="topper.grade"> · {{ frenchGrade(topper.grade) }}</template></span></li></ul></template></div>
