            <div v-if="state.historyError" class="notice error flex items-center justify-between flex-wrap gap-2.5 p-3 mb-3 bg-soft [border-left:3px_solid_var(--accent)] text-[.8rem] [&.error]:text-error [&.error]:bg-error-bg [&.error]:border-l-error [&_button]:px-3 [&_button]:py-2 [&_button]:border [&_button]:border-solid [&_button]:border-[currentColor] [&_button]:rounded-[3px] [&_button]:text-inherit [&_button]:bg-transparent" role="alert">{{ state.historyError }}<button :disabled="state.busy || state.needsLogin" @click="refresh">Retry</button></div>
            <div class="section-heading flex justify-between items-center gap-3 [margin:16px_0_4px] [&_.muted]:text-[.72rem]"><h2>Best ascents</h2><span class="muted text-muted">{{ ranked.length }} / 10</span></div>
